<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Usecase\Retrieve\ThemeVersionRetrieveUsecase;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Usecase\Retrieve\ThemeVersionRetrieveResult;

class ThemeVersionRetrieveController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly ThemeVersionRetrieveUsecase $retrieveUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/document/theme-versions{uid}",
        tags: ["Theme version"],
        description:"Create",
        parameters: [
               new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
          ],
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/ThemeVersionApiDTO")),
              new OA\Response(response: 404, description: "Not found"),
          ]
    )]
    public function retrieve(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Retrieve Theme version");
        $span = $this->startSpan("Retrieve Theme version");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->retrieveUsecase->retrieve($uid);
            $value = $this->mapThemeVersion($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapThemeVersion(ServerRequestInterface $request, ThemeVersionRetrieveResult $value): ThemeVersionApiDTO
    {
        $this->logDebug("Map entity to output dto for Theme version");
        $span = $this->startSpan("Map entity to output dto for Theme version");
        try {
            $theme = $value->getTheme();
            $dto = new ThemeVersionApiDTO();
            $dto->uid = $value->getUid();
            $dto->theme = $theme ? ['$ref' => $theme->uid()] : null;
            $dto->channel = $value->getChannel();
            $dto->locale = $value->getLocale();
            $dto->contentHtml = $value->getContentHtml();
            $dto->contentText = $value->getContentText();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
